int sizeW = sizeWidth;
int sizeH = sizeHeight;

String fileSource = tools.getParamValue("AttachmentStream"); 
String fileType = tools.getParamValue("AttachmentMimeType").toLowerCase(); 
java.io.ByteArrayInputStream arrayInputStream = null;
java.awt.image.BufferedImage originalImage;

if(fileSource.trim().length() > 0) {
	byte[] decodedFileSourceArr = Base64Util.decodeToByteArray(fileSource);
	if(decodedFileSourceArr.length > 0) {
		arrayInputStream = new java.io.ByteArrayInputStream(decodedFileSourceArr);
	}
}else{
	return false;
}

try {
	originalImage = javax.imageio.ImageIO.read(arrayInputStream);
} catch(Exception e) {
	oLog.error("ImageIO exception while reading image");
	return false;
}



int TYPE = originalImage.getType() == 0? java.awt.image.BufferedImage.TYPE_INT_ARGB : originalImage.getType();


int orignalImageHeight=originalImage.getHeight();
int originalImageWidth=originalImage.getWidth();
java.awt.image.BufferedImage resizedImage;

int resizedImageWidth=originalImageWidth - (originalImageWidth*rezisepercent/100);
int resizedImageHeight=orignalImageHeight - (orignalImageHeight*rezisepercent/100) ;

 resizedImage = new java.awt.image.BufferedImage(resizedImageWidth, resizedImageHeight, TYPE);
 java.awt.Graphics2D g = resizedImage.createGraphics();
 g.drawImage(originalImage, 0, 0, resizedImageWidth, resizedImageHeight, null);
 g.dispose();
 g.setComposite(java.awt.AlphaComposite.Src);
 g.setRenderingHint(java.awt.RenderingHints.KEY_INTERPOLATION, java.awt.RenderingHints.VALUE_INTERPOLATION_BILINEAR);
 g.setRenderingHint(java.awt.RenderingHints.KEY_RENDERING, java.awt.RenderingHints.VALUE_RENDER_QUALITY);
 g.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING, java.awt.RenderingHints.VALUE_ANTIALIAS_ON);

java.io.ByteArrayOutputStream outputStream = new java.io.ByteArrayOutputStream();
try {
	javax.imageio.ImageIO.write((java.awt.image.RenderedImage)resizedImage, fileType, outputStream);
} catch(Exception e) {
	oLog.error("ImageIO exception while writing image");
	return false;
}
resizedFileb64 = Base64Util.encodeToString(outputStream.toByteArray());

tools.putParamValue("InputHeight",orignalImageHeight);
tools.putParamValue("InputWidth",originalImageWidth);

